import{_ as o,o as t,c as n,a2 as i}from"./chunks/framework.Boholvbs.js";const r="/docs/assets/ai-geolocation.B4gcRszE.png",a="/docs/assets/ai-geolocation2.BUETwwPx.png",s="/docs/assets/ai-geolocation3.CDR6uScq.png",c="/docs/assets/ai-geolocation4.DlkGYpaD.png",b=JSON.parse('{"title":"AI Georeferencing","description":"","frontmatter":{},"headers":[],"relativePath":"ai-georeferencing.md","filePath":"ai-georeferencing.md"}'),l={name:"ai-georeferencing.md"};function g(d,e,h,p,u,m){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-georeferencing" tabindex="-1">AI Georeferencing <a class="header-anchor" href="#ai-georeferencing" aria-label="Permalink to &quot;AI Georeferencing&quot;">​</a></h1><p>JEO can automatically georeference your posts using AI. Instead of manually searching and adding geolocation points, the AI analyzes your post content and suggests relevant locations with coordinates and confidence scores.</p><p>See <a href="./ai-in-jeo">AI in JEO</a> for an overview of how the AI system works.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>When editing a post, the <strong>Geolocation</strong> sidebar panel includes an <strong>Geolocate with AI</strong> button. Clicking it sends your post title and content to the configured AI provider, which returns suggested geolocation points.</p><p><img src="'+r+'" alt="AI Georeferencing"></p><p><img src="'+a+'" alt="AI Georeferencing"></p><h3 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h3><ol><li>Click <strong>Geolocate with AI</strong> in the Geolocation sidebar panel.</li><li>The AI analyzes the post content and identifies geographic references.</li><li>Suggested points appear with location name, coordinates, and a confidence score.</li><li>Review and approve or adjust the suggested points.</li><li>The points are saved as geolocation data for the post.</li></ol><h2 id="georeferencing-with-custom-prompts" tabindex="-1">Georeferencing with custom prompts <a class="header-anchor" href="#georeferencing-with-custom-prompts" aria-label="Permalink to &quot;Georeferencing with custom prompts&quot;">​</a></h2><p>Under <strong>Jeo → AI → Provider</strong>, you&#39;ll find the <strong>AI Prompt Engineer Assistant</strong> section. Describe how you want the AI to behave (e.g., &quot;Only map cities in Brazil&quot; or &quot;Ignore street names&quot;) and the active LLM will generate an optimized system prompt that incorporates your calibration settings. The generated prompt can be reviewed and edited before use.</p><p><img src="'+s+'" alt="AI Georeferencing - Custom prompts"></p><h3 id="calibration" tabindex="-1">Calibration <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;Calibration&quot;">​</a></h3><p>Under <strong>Jeo → AI → Provider</strong>, in the <strong>Georeferencing Calibration</strong> section, you can fine-tune georeferencing behavior:</p><ul><li><strong>Location Granularity</strong>: Controls the level of geographic detail — Broad (countries, regions), Balanced (cities + neighborhoods), or Fine (streets, landmarks, POIs).</li><li><strong>Minimum Confidence</strong>: Minimum confidence score for a point to be suggested (0–100).</li><li><strong>Primary Threshold</strong>: Confidence score above which a location is classified as PRIMARY (main geographic focus).</li><li><strong>Primary Points</strong>: Maximum number of PRIMARY locations the AI can suggest.</li><li><strong>Secondary Threshold</strong>: Confidence score range for SECONDARY locations (mentioned but not central).</li><li><strong>Secondary Points</strong>: Maximum number of SECONDARY locations the AI can suggest.</li><li><strong>Prioritize Title Mentions</strong>: How much the post title influences the AI&#39;s location detection (0–100%).</li><li><strong>Max Tokens</strong>: Token budget for the generated system prompt.</li></ul><p>Each setting has a <strong>Use</strong> toggle — disable it to exclude that rule from the AI prompt.</p><p><img src="'+c+'" alt="AI Georeferencing - Calibration"></p><h2 id="multi-turn-refinement" tabindex="-1">Multi-turn refinement <a class="header-anchor" href="#multi-turn-refinement" aria-label="Permalink to &quot;Multi-turn refinement&quot;">​</a></h2><p>After the initial georeferencing, you can chat with the AI to refine the results. For example, you can ask it to add a specific city, remove an incorrect point, or adjust the confidence of a suggestion.</p><p>The conversation history is preserved per post, so you can continue refining in subsequent editing sessions.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>An AI provider must be configured in <strong>Jeo → AI</strong> (see <a href="./ai-settings">AI Settings</a>).</li><li>The post must have a title and/or content for the AI to analyze.</li></ul>',22)])])}const A=o(l,[["render",g]]);export{b as __pageData,A as default};
